/* Halqa service worker (generated by scripts/build-sw.js). */
const VERSION = __VERSION__
const PRECACHE = __PRECACHE__
const APP_CACHE = 'halqa-app-' + VERSION
const IMG_CACHE = 'halqa-images'
const RUNTIME_CACHE = 'halqa-runtime'

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(APP_CACHE)
      .then(cache => cache.addAll(PRECACHE.map(u => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  )
})

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('halqa-app-') && k !== APP_CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  )
})

async function cacheFirst(request, cacheName, fallbackUrl) {
  const cached = await caches.match(fallbackUrl || request, { ignoreSearch: !!fallbackUrl })
  if (cached) return cached
  try {
    const res = await fetch(request)
    if (res && (res.ok || res.type === 'opaque')) {
      const cache = await caches.open(cacheName)
      cache.put(request, res.clone())
    }
    return res
  } catch (e) {
    const fallback = fallbackUrl && (await caches.match(fallbackUrl))
    if (fallback) return fallback
    throw e
  }
}

self.addEventListener('fetch', event => {
  const req = event.request
  if (req.method !== 'GET') return
  const url = new URL(req.url)

  // The app itself: always served from the cache so it opens instantly, with
  // or without signal. New versions install in the background.
  if (req.mode === 'navigate' && url.origin === self.location.origin) {
    event.respondWith(cacheFirst(req, APP_CACHE, '/'))
    return
  }
  if (url.origin === self.location.origin) {
    event.respondWith(cacheFirst(req, RUNTIME_CACHE))
    return
  }
  // Photos from Supabase Storage: keep a copy once seen, so they show offline.
  if (url.pathname.includes('/storage/v1/object/public/')) {
    event.respondWith(cacheFirst(req, IMG_CACHE))
  }
  // Everything else (database API, Claude API) goes straight to the network.
})
